def _persona(g: dict) -> dict:
    p = _base_persona(g)
    p['visual_identity'].pop('art_style', None)  # photographed, like the rest of the roster
    p['visual_identity']['identity_version'] = f"{g['folder']}_v1_2026_10_23"
    return p


def _plots() -> None:
    p = ROOT / 'services' / 'storylines_data.py'
    text = p.read_text(encoding='utf-8')
    for g in GIRLS:
        if f"    '{g['id']}': [" in text:
            continue
        rows = ''
        for key, emoji, title, teaser, her, his, place, opening in g['plots']:
            rows += (f'        ({base.q(key)}, {base.q(emoji)}, {base.q(title)}, {base.q(teaser)},\n'
                     f'         {base.q(her)}, {base.q(his)},\n'
                     f'         {base.q(place)},\n'
                     f'         {base.q(opening)}),\n')
        head, tail = text.rsplit('\n}', 1)
        text = head + f"\n    '{g['id']}': [\n{rows}    ]," + '\n}' + tail
    p.write_text(text, encoding='utf-8')


def main() -> None:
    base.GIRLS = GIRLS
    base._persona = _persona
    base.main()
    _plots()


if __name__ == '__main__':
    main()
    print('V379_GIRLS_INSTALLED')
